"""Every case in conformance/contracts.v1.json, generated by the TypeScript reference."""

import json
from pathlib import Path

import pytest

from super_router import RouterError
from super_router.contracts import canonical, parse_invocation, parse_service

DATA = json.loads((Path(__file__).resolve().parents[3] / "conformance" / "contracts.v1.json").read_text())


@pytest.mark.parametrize("case", DATA["service"], ids=lambda c: c["name"])
def test_service(case):
    expect = case["expect"]
    if "error" in expect:
        with pytest.raises(RouterError) as raised:
            parse_service(case["input"])
        assert (raised.value.code, raised.value.status) == (expect["error"], 400)
    else:
        assert parse_service(case["input"]) == expect["ok"]


@pytest.mark.parametrize("case", DATA["invocation"], ids=lambda c: c["name"])
def test_invocation(case):
    expect = case["expect"]
    if "error" in expect:
        with pytest.raises(RouterError) as raised:
            parse_invocation(case["input"])
        assert (raised.value.code, raised.value.status) == (expect["error"], 400)
    else:
        parsed = parse_invocation(case["input"])
        assert parsed == expect["ok"]
        assert canonical(parsed) == expect["canonical"]


def test_counts():
    assert len(DATA["service"]) >= 50 and len(DATA["invocation"]) >= 30


@pytest.mark.parametrize("value", [None, [], "x", 1, True, {}, {"a": 1}])
def test_garbage(value):
    with pytest.raises(RouterError):
        parse_invocation(value)
    with pytest.raises(RouterError):
        parse_service(value)
